+
+ const RULER_STEP = 3;
+ /* 47-01 UAT round 5: 18px-wide × 22px-tall frames (user test request). This
+    drives lane width, ruler ticks, drag/scroll math, and the per-cell grid; one
+    ruler tick spans RULER_STEP cells (3 × 18px = 54px). */
+ const ROTO_CELL_WIDTH_PX = 18;
+ /** One ruler tick spans RULER_STEP abutting cells (3 × 18px = 54px). */
+ const RULER_TICK_WIDTH_PX = RULER_STEP * ROTO_CELL_WIDTH_PX;
+
+ /* 47-01 UAT round 3: flexible strip height. The fixed chrome bands are
+    46 (header) + 1 (strip border) + 1 (timeline border) + 36 (ruler, the
+    52.5-01b D-07 band 28 -> 36 for the waveform stain) + 34 (action row) +
+    14 (scrollbar), i.e. 46 + 1 + 1 + 36 + 34 + 14 = 132. The strip
+    defaults to exactly enough
+    height for every track row + the Bg row (31px each — 30px layout + 1px
+    between stacked rows, v2.0.1 UAT), capped at 270px so the canvas keeps
+    room; the top-edge drag handle lets the user shrink (vertical scroll
+    appears) or grow up to the full content height — never beyond the number
+    of tracks. */
+ // 47-01 UAT round 7: the row is 31px (6px rail band + 22px cells + 3px floor).
+ const STRIP_ROW_HEIGHT_PX = 31;
+ const STRIP_CHROME_HEIGHT_PX = 132;
+ const STRIP_MAX_HEIGHT_PX = 270;
+ const STRIP_MIN_ROWS = 1;
+
+ /** 59-11 (MUI-04/MUI-05): the ONE measured row layout. Every rail row is one
+  *  strip row unit (31px) tall; an expanded motion block adds one
+  *  `TIMELINE_MOTION.laneHeight` row per VISIBLE display lane (grouped Position
+  *  counts once, so the maximum is four) plus a single post-block gap. The
+  *  content height, the header column and the reorder insertion index all read
+  *  this array — there is no second height derivation anywhere. */
+ export interface TrackRowLayoutInput {
+   readonly trackId: string;
+   /** Visible DISPLAY-lane count for this row (0 for every row whose block is
+    *  closed, which is every row except the expanded one). */
+   readonly laneCount: number;
+   /** 59-17: the expanded block renders the 18px `+` add-channel row while a
+    *  display lane is still keyless. It is part of the measured height. */
+   readonly addChannelRow?: boolean;
+ }
+
+ export interface TrackRowLayoutEntry {
+   readonly trackId: string;
+   /** Row top in the strip's scroll content, in px. */
+   readonly offset: number;
+   /** The rail/cell band — always one row unit. */
+   readonly railHeight: number;
+   /** Clamped visible display-lane count. */
+   readonly laneCount: number;
+   /** Whether the measured height includes the 59-17 add-channel row. */
+   readonly addChannelRow: boolean;
+   /** railHeight + lanes × laneHeight + (lanes > 0 ? postBlockGap : 0)
+    *  + (addChannelRow ? laneHeight : 0). */
+   readonly height: number;
+ }
+
+ export interface TrackRowLayout {
+   readonly rows: readonly TrackRowLayoutEntry[];
+   readonly totalHeight: number;
+ }
+
+ /** The display projection can never exceed four rows (59-10). */
+ const MAX_MOTION_DISPLAY_LANES = 4;
+
+ /** The reorder band's geometry: viewport top + the band's current scroll. */
+ export interface ReorderBandMetrics {
+   readonly top: number;
+   readonly scrollTop: number;
+ }
+
+ /**
+  * 59-11 Task 3 (MUI-05, T-59-31): the measured, block-aware reorder insertion
+  * index. Walks the ONE layout array and returns the index of the row whose
+  * RAIL band contains the point, clamped to `[0, layout.length - 1]`.
+  *
+  * A point inside an expanded channel block resolves to that block's OWN rail
+  * index — never to a neighbouring row and never to a fractional position
+  * between lanes. With no lanes this is exactly the pre-59-11 uniform
+  * computation (`floor(y / rowUnit)`), because every height is one row unit.
+  */
+ export function resolveReorderInsertionIndex(
+   clientY: number,
+   band: ReorderBandMetrics,
+   layout: readonly TrackRowLayoutEntry[],
+ ): number {
+   const lastIndex = layout.length - 1;
+   if (lastIndex < 0) return 0;
+   const contentY = clientY - band.top + band.scrollTop;
+   if (!Number.isFinite(contentY) || contentY <= 0) return 0;
+   for (let index = 0; index <= lastIndex; index += 1) {
+     const entry = layout[index]!;
+     if (contentY < entry.offset + entry.height) return index;
+   }
+   return lastIndex;
+ }
+
+ export function resolveTrackRowLayout(
+   rows: readonly TrackRowLayoutInput[],
+ ): TrackRowLayout {
+   // The strip always supplies the placeholder row for an empty document, so
+   // no rows here genuinely means no content (total 0), never a hidden 31.
+   const railHeight = STRIP_ROW_HEIGHT_PX;
+   const entries: TrackRowLayoutEntry[] = [];
+   let offset = 0;
+   for (const row of rows) {
+     const laneCount = Number.isFinite(row.laneCount)
+       ? Math.max(0, Math.min(MAX_MOTION_DISPLAY_LANES, Math.floor(row.laneCount)))
+       : 0;
+     // 59-17: the add-channel row only exists inside an OPEN block, so a zero
+     // lane count swallows the flag instead of reserving dead height.
+     const addChannelRow = row.addChannelRow === true && laneCount > 0;
+     const height = railHeight
+       + laneCount * TIMELINE_MOTION.laneHeight
+       + (laneCount > 0 ? TIMELINE_MOTION.postBlockGap : 0)
+       + (addChannelRow ? TIMELINE_MOTION.laneHeight : 0);
+     entries.push({ trackId: row.trackId, offset, railHeight, laneCount, addChannelRow, height });
+     offset += height;
+   }
+   return { rows: entries, totalHeight: offset };
+ }
+
+ /** 52.5-01b Task 3: the live sound-band gesture session (identity fixed at
+  *  pointer-down; `next` is the clamped preview state, `origin` the commit
+  *  baseline for rejected settles). */
+ interface SoundBandGestureSession {
+   /** 261008-ig1 Task 3: `'duplicate'` joins the union — the bare-alt clone
+    *  intent is stamped at pointer-down and never switches mid-gesture. */
+   readonly kind: SoundBandGestureKind;
+   /** 261008-ig1 Task 2: the clip this gesture drives — stamped once at
+    *  pointer-down; the settle payload routes through the per-clip door. */
+   readonly clipId: string;
+   readonly pointerId: number;
+   readonly originX: number;
+   readonly origin: SoundBandValues;
+   armed: boolean;
+   next: SoundBandValues;
+   removeWindowListeners: () => void;
+ }
+
+ /** Per-clip DOM handles the gesture preview mutates directly (no per-move
+  *  strip re-render). One record per clip id, created on first sight. */
+ interface SoundClipDomEls {
+   stain: HTMLDivElement | null;
+   wave: SVGSVGElement | null;
+   overlay: SVGGElement | null;
+   edgeStart: HTMLDivElement | null;
+   edgeEnd: HTMLDivElement | null;
+ }
+
+ /**
+  * 47-02 Task 3 (TML-03/D-05): the pure ensure-active-row-visible delta.
+  * Given one row's lane bounds and the rows-region viewport bounds, all in
+  * CONTENT coordinates (lane = absolute scrollable content position;
+  * viewportTop = current scrollTop; viewportBottom = scrollTop + clientHeight),
+  * returns the scrollTop adjustment that brings the row into view:
+  * - row below the viewport → positive delta aligning the row's bottom with
+  *   the viewport's bottom;
+  * - row above the viewport → negative delta aligning the row's top with the
+  *   viewport's top;
+  * - fully visible → 0.
+  * A row TALLER than the viewport can never be fully visible, so the delta
+  * clamps to align the row's TOP with the viewport's top (never scrolls past
+  * the row's own top). The caller additionally clamps the result to the
+  * scroll extent; this function stays pure so the test can prove the whole
+  * geometry table without a DOM.
+  */
+ export function computeEnsureRowScrollDelta(
+   laneTop: number,
+   laneBottom: number,
+   viewportTop: number,
+   viewportBottom: number,
+ ): number {
+   const laneHeight = laneBottom - laneTop;
+   const viewportHeight = viewportBottom - viewportTop;
+   if (laneHeight >= viewportHeight) {
+     // Taller-than-viewport row: pin the row's top to the viewport's top.
+     return laneTop - viewportTop;
+   }
+   if (laneTop < viewportTop) return laneTop - viewportTop;
+   if (laneBottom > viewportBottom) return laneBottom - viewportBottom;
+   return 0;
+ }
+ const EMPTY_LOOP_PRESENTATIONS: ReadonlyMap<string, PhysicsPaintLoopClipPresentation> = new Map();
+ const EMPTY_SPACING_PROXIES: ReadonlyMap<number, PhysicsPaintRotoSpacingProxy> = new Map();
+ const EMPTY_CACHED_ROTO_FRAMES: readonly PhysicPaintRotoCacheFrame[] = [];
+ const EMPTY_STRING_IDS: readonly string[] = [];
+ const EMPTY_KEY_ID_SET: ReadonlySet<string> = new Set<string>();
+ const EMPTY_RAIL_SET_MOVE_MEMBERS: readonly PhysicPaintRailSetMoveMember[] = [];
+ const EMPTY_RAIL_SET_GAP_PREVIEW_FRAMES: ReadonlySet<number> = new Set<number>();
+ const NOOP_KEY_RAIL_SELECTION = (_selection: RotoKeyRailSelection): void => {};
+
+ function buildRulerTicks(frameCells: number[]): number[] {
+   return frameCells.filter((frame) => frame % RULER_STEP === 0);
+ }
+
+ interface RotoTimelineStructuralIndex {
+   readonly frameCells: number[];
+   readonly physicalCellByAppFrame: ReadonlyMap<number, RotoPhysicalTimelineCell>;
+   readonly generatedRotoFrames: readonly number[];
+   readonly cachedFrameByAppFrame: ReadonlyMap<number, PhysicPaintRotoCacheFrame>;
+   readonly realCachedFrameSet: ReadonlySet<number>;
+   readonly lifecycleTargetByAppFrame: ReadonlyMap<number, PhysicPaintRotoGroupFrameTarget>;
+ }
+
+ /**
+  * The strip's sole physical extent boundary. A projection is safe to render
+  * only when every array position names that same physical frame; otherwise a
+  * partial, duplicate, or reordered input could silently create a second extent.
+  */
+ export function buildRotoTimelineStructuralIndex(
+   physicalCells: readonly RotoPhysicalTimelineCell[],
+   cachedFrames: readonly PhysicPaintRotoCacheFrame[],
+   acceptedGroupDocument: Pick<PhysicPaintRotoPhysicalDocument, 'realKeyRecords' | 'loopClips'>,
+   classifyTarget: typeof classifyPhysicPaintRotoGroupFrameTarget = classifyPhysicPaintRotoGroupFrameTarget,
+ ): RotoTimelineStructuralIndex {
+   if (physicalCells.length === 0 || physicalCells.length > PHYSIC_PAINT_MAX_APPLY_FRAMES) {
+     throw new Error(`Invalid Roto physical projection length: expected 1 to ${PHYSIC_PAINT_MAX_APPLY_FRAMES} cells.`);
+   }
+   const frameCells: number[] = [];
+   const physicalCellByAppFrame = new Map<number, RotoPhysicalTimelineCell>();
+   const generatedRotoFrames: number[] = [];
+   const cachedFrameByAppFrame = new Map<number, PhysicPaintRotoCacheFrame>();
+   const realCachedFrameSet = new Set<number>();
+   for (const cachedFrame of cachedFrames) {
+     const existing = cachedFrameByAppFrame.get(cachedFrame.appFrame);
+     if (!existing || (existing.source !== 'real-key' && cachedFrame.source === 'real-key')) {
+       cachedFrameByAppFrame.set(cachedFrame.appFrame, cachedFrame);
+     }
+     if (cachedFrame.source === 'real-key') realCachedFrameSet.add(cachedFrame.appFrame);
+   }
+
+   const lifecycleTargetByAppFrame = new Map<number, PhysicPaintRotoGroupFrameTarget>();
+   for (let appFrame = 0; appFrame < physicalCells.length; appFrame += 1) {
+     const cell = physicalCells[appFrame];
+     if (!cell || cell.appFrame !== appFrame) {
+       throw new Error(`Invalid Roto physical projection at index ${appFrame}: expected appFrame ${appFrame}.`);
+     }
+     frameCells.push(appFrame);
+     physicalCellByAppFrame.set(appFrame, cell);
+     if (cell.kind === 'generated') {
+       generatedRotoFrames.push(appFrame);
+       if (!cachedFrameByAppFrame.has(appFrame)) {
+         cachedFrameByAppFrame.set(appFrame, {
+           frameIndex: 0,
+           appFrame,
+           bytes: new Uint8Array(0),
+           source: 'generated-interpolation',
+         });
+       }
+     }
+     lifecycleTargetByAppFrame.set(appFrame, classifyTarget({
+       document: acceptedGroupDocument,
+       appFrame,
+     }));
+   }
+   return { frameCells, physicalCellByAppFrame, generatedRotoFrames, cachedFrameByAppFrame, realCachedFrameSet, lifecycleTargetByAppFrame };
+ }
+
+
+
+ function isSavedFrame(markers: PhysicsPaintWorkflowStripFrameMarker[] | undefined, frame: number): boolean {
+   return Boolean(markers?.some(marker => marker.frame === frame && marker.saved !== false && marker.source !== 'generated-interpolation'));
+ }
+
+ /**
+  * Shared guarded-action tooltip copy (36.15-08, UAT Gap D). The tooltip shows
+  * only the description or 'unavailable: {verbatim controller reason}' — the
+  * Plan 01 '{Action} — ' tool-name prefix is dropped because every bottom-row
+  * action now carries a short visible label next to its icon.
+  */
+ function buildGuardedActionTooltipCopy(description: string, disabledReason: string | null): string {
+   return disabledReason ? `unavailable: ${disabledReason}` : description;
+ }
+
+ export interface PhysicsPaintRotoMotionKeyControlsProps {
+   /** The one resolved selection scope; controls exist ONLY in the motion-key scope. */
+   readonly scope: RailMotionSelectionScope | null;
+   readonly easing: PhysicPaintRotoRailMotionEasing | null;
+   readonly wiggle: number | null;
+   readonly canSetEasing: boolean;
+   readonly canSetWiggle: boolean;
+   readonly easingDisabledReason: string | null;
+   readonly wiggleDisabledReason: string | null;
+   readonly onSetEasing: (easing: PhysicPaintRotoRailMotionEasing) => void;
+   readonly onSetWiggle: (wiggle: number) => void;
+ }
+
+ /**
+  * 59-12 Task 2 (MOTN-05): the selected Motion key's Hold/Ease toggle and
+  * Wiggle field. A drawing-key or rail scope renders NOTHING here — the
+  * commands belong to another scope, so they are absent, not disabled. Pure and
+  * hook-free so the scope-visibility rows can materialize it directly.
+  */
+ export function PhysicsPaintRotoMotionKeyControls(props: PhysicsPaintRotoMotionKeyControlsProps) {
+   if (props.scope !== 'motion-key' || props.easing === null || props.wiggle === null) return null;
+   const easingDisabled = !props.canSetEasing;
+   const wiggleDisabled = !props.canSetWiggle;
+   return (
+     <span
+       class="physics-paint-roto-key-icon-action physics-paint-roto-motion-key-controls"
+       role="group"
+       aria-label="Selected Motion key"
+       data-roto-motion-key-controls="true"
+     >
+       <button
+         type="button"
+         class="physics-paint-roto-key-icon-button"
+         aria-label="Hold motion key"
+         aria-pressed={props.easing === 'hold' ? 'true' : 'false'}
+         aria-disabled={easingDisabled ? 'true' : undefined}
+         aria-describedby={easingDisabled && props.easingDisabledReason ? 'roto-key-action-reason-motion-easing' : undefined}
+         onClick={() => {
+           if (!easingDisabled) props.onSetEasing('hold');
+         }}
+       >
+         Hold
+       </button>
+       <button
+         type="button"
+         class="physics-paint-roto-key-icon-button"
+         aria-label="Ease motion key"
+         aria-pressed={props.easing === 'ease' ? 'true' : 'false'}
+         aria-disabled={easingDisabled ? 'true' : undefined}
+         aria-describedby={easingDisabled && props.easingDisabledReason ? 'roto-key-action-reason-motion-easing' : undefined}
+         onClick={() => {
+           if (!easingDisabled) props.onSetEasing('ease');
+         }}
+       >
+         Ease
+       </button>
+       <span class="physics-paint-roto-key-icon-label">Wiggle</span>
+       <NumericStepper
+         value={props.wiggle}
+         onChange={(value) => {
+           if (!wiggleDisabled) props.onSetWiggle(value);
+         }}
+         step={1}
+         min={0}
+         ariaLabel="Motion key wiggle"
+         ariaDisabled={wiggleDisabled}
+         ariaDescribedBy={wiggleDisabled && props.wiggleDisabledReason ? 'roto-key-action-reason-motion-wiggle' : undefined}
+         inputStyle={{ width: '44px' }}
+         buttonStyle={{ width: '18px' }}
+       />
+       {easingDisabled && props.easingDisabledReason ? (
+         <span id="roto-key-action-reason-motion-easing" class="physics-paint-sr-only">{props.easingDisabledReason}</span>
+       ) : null}
+       {wiggleDisabled && props.wiggleDisabledReason ? (
+         <span id="roto-key-action-reason-motion-wiggle" class="physics-paint-sr-only">{props.wiggleDisabledReason}</span>
+       ) : null}
+     </span>
+   );
+ }
+
+ /** 261022-cfn follow-up: a linked Rail repeat is any virtual linked occurrence
+  *  past the source cycle — 'linked-unresolved' (always a repeat) or a
+  *  linked/linked-generated/linked-gap cell with repeatInstance > 0. The + Rail
+  *  button greys on these so it can never break a linked repeat silently. */
+ function isLinkedRepeatFrameResolution(resolution: PhysicPaintRotoFrameResolution | null | undefined): boolean {
+   return resolution?.kind === 'linked-unresolved'
+     || ((resolution?.kind === 'linked'
+       || resolution?.kind === 'linked-generated'
+       || resolution?.kind === 'linked-gap')
+       && resolution.repeatInstance > 0);
+ }
+
+ type RotoDragCandidateKind = 'empty' | 'real-key' | 'generated' | 'outside' | 'locked';
+ interface RotoDragPreviewState {
+   movedKeyId: string;
+   sourceAppFrame: number;
+   publication: RotoDragPublication | null;
+   candidateKind: RotoDragCandidateKind;
+   candidateValid: boolean;
+   error: string | null;
+   pending: boolean;
+   /** True when the gesture session is a group drag (selection >= 2 containing the grabbed key). */
+   groupDrag: boolean;
+   /** Resolver-supplied blocked destination frames for the blocked-target preview (D-08); null otherwise. */
+   conflictingAppFrames: readonly number[] | null;
+ }
+
+ interface RotoDragGestureSession {
+   pointerId: number;
+   movedKeyId: string;
+   sourceAppFrame: number;
+   sourceElement: HTMLButtonElement;
+   originX: number;
+   originY: number;
+   latestX: number;
+   latestY: number;
+   started: boolean;
+   groupDrag: boolean;
+   candidateTarget: RotoDragTarget | null;
+   candidateKind: RotoDragCandidateKind;
+   candidateValid: boolean;
+   candidateError: string | null;
+   /** Group-preparation failure detail retained for release-time publication (D-07/D-09); null on single-key paths. */
+   candidateConflicts: readonly number[] | null;
+   candidateDetail: string | null;
+   publication: RotoDragPublication | null;
+   rafId: number | null;
+   lastRafTime: number | null;
+   validityKey: string;
+   cleanup: () => void;
+ }
+
+ const ROTO_DRAG_THRESHOLD_PX = 6;
+ const ROTO_EDGE_SCROLL_ZONE_PX = 32;
+ const ROTO_EDGE_SCROLL_MIN_PX_PER_SECOND = 40;
+ const ROTO_EDGE_SCROLL_MAX_PX_PER_SECOND = 160;
+
+ /**
+  * Identity-based target signature equality (D-09). Two targets are equal when
+  * their kind, resolved appFrame (for physical-cell), and targetKeyId (for
+  * before-key/after-key) all match. The strip uses this to require that the
+  * pointer-up release target matches the retained publication's target
+  * signature before committing — preventing stale or sliding-target commits.
+  */
+ function targetSignaturesEqual(
+   target: RotoDragTarget,
+   signature: RotoDragTargetSignature,
+ ): boolean {
+   if (target.kind !== signature.kind) return false;
+   if (target.kind === 'physical-cell') {
+     if (signature.kind !== 'physical-cell') return false;
+     return (target.appFrame ?? null) === (signature.appFrame ?? null);
+   }
+   // before-key / after-key
+   if (signature.kind === 'physical-cell') return false;
+   return (target.targetKeyId ?? null) === (signature.targetKeyId ?? null);
+ }
+
+ /**
+  * Locate a mounted Roto key cell by its opaque bounded key identity (CR-04).
+  * Key IDs are opaque resolver strings; interpolating them into a CSS
+  * attribute selector can throw for valid CSS-string edge cases, so the lookup
+  * compares `dataset.rotoKeyId` directly instead of building a selector.
+  */
+ function findRotoKeyCellByKeyId(scroller: HTMLElement, keyId: string): HTMLElement | null {
+   for (const cell of scroller.querySelectorAll<HTMLElement>('[data-roto-key-id]')) {
+     if (cell.dataset.rotoKeyId === keyId) return cell;
+   }
+   return null;
+ }
+
+ function getRotoDragFeedback(preview: RotoDragPreviewState | null): string | null {
+   if (!preview) return null;
+   if (preview.pending) {
+     return preview.publication
+       ? getRotoDragPreviewViewModel(preview.publication.proposal, { committing: true }).conciseStatus
+       : 'Committing Roto key move...';
+   }
+   if (!preview.candidateValid || !preview.publication) return preview.error;
+   return getRotoDragPreviewViewModel(preview.publication.proposal).conciseStatus;
+ }
+
+ /**
+  * 38.1-D-01 live surface 2: the minimal current-frame indicator — the EXISTING
+  * nav-pill element `<output class="physics-paint-current-frame">` (Open
+  * Question 1 RESOLVED: element, class, and placement pinned, unchanged).
+  * During active cached playback it reads the per-tick playback appFrame signal
+  * (only this child re-renders per tick); otherwise it shows props.currentFrame
+  * exactly as before. The signal is never read when playback is inactive, so an
+  * idle strip holds zero per-tick subscriptions.
+  *
+  * 261105-cgl Task 2: the readout is now the go-to-frame trigger. The output
+  * element/class/content/placement are untouched; the popover is anchored to a
+  * zero-chrome button wrapping it. The mode/draft state is local session UI —
+  * nothing is persisted, and the popover never follows playback ticks while
+  * open (the draft seeds once on open from the live read). Every commit resolves
+  * through the pure `resolveFrameGotoTarget` (finite-checked, rounded, clamped)
+  * before it reaches the Studio's existing synced-frame navigation path.
+  */
+ function RotoPlaybackCurrentFrameOutput(props: {
+   currentFrame: Signal<number>;
+   playbackActive: boolean;
+   playbackTick: Signal<RotoCachedPlaybackTick | null> | null | undefined;
+   /** Project fps — the Frame<->Seconds unit law (playback fps never applies). */
+   fps?: number;
+   /** Last reachable frame index; every entry clamps into [0, lastFrame]. */
+   lastFrame?: number;
+   onGoToFrame?: (frame: number) => void;
+ }) {
+   const playbackAppFrame = props.playbackActive ? props.playbackTick?.value?.appFrame ?? null : null;
+   const frame = playbackAppFrame ?? props.currentFrame.value;
+   const lastFrame = Math.max(0, props.lastFrame ?? 0);
+   const fps = props.fps ?? 1;
+   // 261105-cgl UAT: local popup state is signal-backed (the project's
+   // reactivity law) so the unit switch re-renders deterministically.
+   const open = useSignal(false);
+   // Shared timeline unit — the switch also retimes the ruler tick labels.
+   const unitMode = getTimelineUnitMode();
+   // The canonical position, kept in FRAMES. Both units display the same
+   // position, so switching Frame<->Seconds never re-derives or drifts.
+   const draftFrame = useSignal(0);
+   const triggerRef = useRef<HTMLButtonElement | null>(null);
+   const panelRef = useRef<HTMLDivElement | null>(null);
+
+   const closeFrameGoto = useCallback(() => { open.value = false; }, []);
+
+   // Dismissal mirrors the Tools popover's one-layer rule: listeners exist only
+   // while open, and Escape consumes the key before the Studio dispatcher (one
+   // Escape handles at most one layer). No backdrop, no focus trap.
+   useEffect(() => {
+     if (!open.value) return;
+     const onPointerDown = (event: PointerEvent) => {
+       if (!shouldDismissToolboxPopover(event.target, [triggerRef.current, panelRef.current])) return;
+       // Commit a typed value before the panel unmounts: the stepper commits on
+       // blur, and closing first would drop the entry (UAT "no work").
+       const active = typeof document !== 'undefined' ? document.activeElement : null;
+       if (active instanceof HTMLElement && panelRef.current?.contains(active)) active.blur();
+       closeFrameGoto();
+     };
+     const onEscapeKeyDown = (event: KeyboardEvent) => {
+       if (event.key !== 'Escape') return;
+       event.stopImmediatePropagation();
+       closeFrameGoto();
+     };
+     window.addEventListener('pointerdown', onPointerDown, true);
+     window.addEventListener('keydown', onEscapeKeyDown, true);
+     return () => {
+       window.removeEventListener('pointerdown', onPointerDown, true);
+       window.removeEventListener('keydown', onEscapeKeyDown, true);
+     };
+   }, [open.value, closeFrameGoto]);
+
+   const openFrameGoto = () => {
+     // The unit is a timeline display choice — it survives close/reopen.
+     // Seed ONCE from the live read — the popover never follows playback ticks.
+     const live = props.playbackActive
+       ? props.playbackTick?.peek()?.appFrame ?? props.currentFrame.peek()
+       : props.currentFrame.peek();
+     draftFrame.value = normalizeFrameGotoFrame(live, lastFrame) ?? 0;
+     open.value = true;
+   };
+
+   const commitFrameGoto = (value: number) => {
+     const target = resolveFrameGotoTarget(unitMode, value, fps, lastFrame);
+     if (target === null) return;
+     draftFrame.value = target;
+     props.onGoToFrame?.(target);
+   };
+
+   const displayValue = resolveFrameGotoValue(unitMode, draftFrame.value, fps);
+   const frameMode = unitMode === 'frame';
+
+   return (
+     <Fragment>
+       <button
+         ref={triggerRef}
+         type="button"
+         class="physics-paint-current-frame-trigger"
+         aria-haspopup="dialog"
+         aria-expanded={open.value}
+         aria-controls={open.value ? 'physics-paint-frame-goto-popover' : undefined}
+         aria-label={`Frame ${frame} — open the go-to-frame popup`}
+         title="Frame — click to go to a frame"
+         onClick={() => { if (open.value) closeFrameGoto(); else openFrameGoto(); }}
+       >
+         <output class="physics-paint-current-frame">{playbackAppFrame ?? props.currentFrame.value}</output>
+       </button>
+       <PhysicsPaintToolboxPopover
+         anchorRef={triggerRef}
+         panelRef={panelRef}
+         open={open.value}
+         panelId="physics-paint-frame-goto-popover"
+         className="physics-paint-frame-goto-popover"
+         ariaLabel="Go to frame"
+         dismissExempt
+       >
+         <div class="physics-paint-frame-goto-mode" role="group" aria-label="Go-to unit">
+           <button
+             type="button"
+             aria-pressed={frameMode}
+             // UAT: switch on pointerdown as well as click — the unit must
+             // change the instant the press lands, before any dismissal path.
+             onPointerDown={(event) => { event.preventDefault(); setTimelineUnitMode('frame'); }}
+             onClick={() => { setTimelineUnitMode('frame'); }}
+           >Frame</button>
+           <button
+             type="button"
+             aria-pressed={!frameMode}
+             onPointerDown={(event) => { event.preventDefault(); setTimelineUnitMode('seconds'); }}
+             onClick={() => { setTimelineUnitMode('seconds'); }}
+           >Seconds</button>
+         </div>
+         <label class="physics-paint-frame-goto-field">
+           <span>{frameMode ? 'Frame number' : 'Time in seconds'}</span>
+           <NumericStepper
+             value={displayValue}
+             onChange={commitFrameGoto}
+             min={0}
+             max={frameMode ? lastFrame : framesToSeconds(lastFrame, fps)}
+             step={frameMode ? undefined : 0.1}
+             precision={frameMode ? undefined : 2}
+             ariaLabel={frameMode ? 'Frame number' : 'Time in seconds'}
+             class="physics-paint-frame-goto-stepper"
+           />
+         </label>
+       </PhysicsPaintToolboxPopover>
+     </Fragment>
+   );
+ }
+
+ /**
+  * 260827-s52 Task 2: the full-height playhead bar — a 2px accent line overlaying
+  * the ruler, every track row, and the Bg row at the current frame. It derives
+  * from the EXISTING current-frame signal plus (only while playback is active)
+  * the per-tick playback signal — mirroring RotoPlaybackCurrentFrameOutput, so
+  * an idle strip holds zero per-tick subscriptions and only this leaf re-renders
+  * per tick during playback. No new position state exists here: cursorAppFrame
+  * (props.currentFrame, fed by launchContext.startFrame) stays the single
+  * position source, so the bar follows seeks, cell navigation, playback ticks,
+  * and undo/redo restores for free. CSS enforces pointer-events: none (T-s52-03).
+  */
+ function PhysicsPaintPlayheadBar(props: { currentFrame: Signal<number>; scrubFrame?: ReadonlySignal<number | null>; playbackActive: boolean; playbackTick: Signal<RotoCachedPlaybackTick | null> | null | undefined; frameCount: number; onHandlePointerDown?: (event: PointerEvent) => void }) {
+   // G-52-9 drag-gate: while the ruler scrub gesture is armed the scrub feed
+   // wins — this leaf is the ONLY strip UI that follows the drag (the Studio
+   // runs no startFrame propagation mid-drag, so props.currentFrame holds the
+   // gesture's origin frame until the release settle).
+   const frame = props.playbackActive
+     ? (props.playbackTick?.value?.appFrame ?? props.currentFrame.value)
+     : (props.scrubFrame?.value ?? props.currentFrame.value);
+   const clampedFrame = Math.max(0, Math.min(frame, Math.max(0, props.frameCount - 1)));
+   // 6 = the v2.0.1 timeline-scroll content gutter (README §3 — the ruler/cell
+   // origin sits 2px further in than the retired 4px padding); +8 = half a cell
+   // (18/2 = 9) minus half the 2px line → the bar centers on the frame.
+   const left = 6 + clampedFrame * ROTO_CELL_WIDTH_PX + 8;
+   return (
+     <>
+       <div class="physics-paint-playhead-bar" aria-hidden="true" style={{ left: `${left}px` }}>
+         {/* UAT round 3: the dedicated scrub handle — a small square on the
+             playhead. Dragging it scrubs without ever touching the clip (the
+             clip is a selection/drag target, never a scrub target). The bar
+             stays pointer-events:none (T-s52-03); only this square takes input. */}
+         <div
+           class="physics-paint-playhead-handle"
+           title="Drag to scrub"
+           onPointerDown={(event) => props.onHandlePointerDown?.(event as unknown as PointerEvent)}
+         ></div>
+       </div>
+       {/* The band-edge continuation: a 1px translucent line spanning the key
+           cells and rows, painted separately so the ruler-band accent keeps its
+           solid 2px weight. +0.5px centres the 1px line on the 2px bar. */}
+       <div
+         class="physics-paint-playhead-trail"
+         aria-hidden="true"
+         style={{ left: `${left + 0.5}px` }}
+       ></div>
+     </>
+   );
+ }
+
+ function PhysicsPaintWorkflowLiveStatus(props: { capsuleText: Signal<string>; isError: boolean; warmProgress?: ReadonlySignal<number> }) {
+   const tooltip = useStyledTooltip();
+   const capsuleText = props.capsuleText.value;
+   const warm = props.warmProgress?.value ?? 0;
+   const warming = warm > 0 && warm < 100;
+   return (
+     <div
+       class={`physics-paint-status-capsule${props.isError ? ' physics-paint-status-capsule-error' : ''}`}
+       role={props.isError ? 'alert' : 'status'}
+       aria-live="polite"
+       onPointerEnter={tooltip.onPointerEnter}
+       onPointerLeave={tooltip.onPointerLeave}
+     >
+       {props.isError
+         ? <TriangleAlert size={16} aria-hidden="true" />
+         : <Info size={16} aria-hidden="true" />}
+       <span class="physics-paint-status-capsule-text">{capsuleText}</span>
+       {warming && (
+         <span class="physics-paint-status-capsule-warm" aria-hidden="true">
+           <span class="physics-paint-status-capsule-warm-fill" style={{ width: `${warm}%` }} />
+         </span>
+       )}
+       <PhysicsPaintStyledTooltip visible={tooltip.visible} region="top">{capsuleText}</PhysicsPaintStyledTooltip>
+     </div>
+   );
+ }
+
+ /**
+  * 59-12 Task 4 (MOTN-10): the merge-drop confirmation row. This leaf alone
+  * subscribes to the session notice signal — the strip body never reads it, so a
+  * notice change re-renders just this row. Inline token styling keeps this task
+  * out of physicsPaintStudio.css. The notice is session-only: publish performs
+  * no store write, no revision bump and creates no undo entry.
+  */
+ function RailMotionMergeNoticeRow() {
+   const notice = railMotionMergeNotice.value;
+   const undoable = railMotionMergeNoticeUndoable.value;
+   if (notice === null) return null;
+   return (
+     <div
+       role="status"
+       aria-live="polite"
+       data-roto-motion-merge-notice="true"
+       style={{
+         display: 'flex',
+         alignItems: 'center',
+         gap: '8px',
+         minHeight: '24px',
+         margin: '0 8px',
+         padding: '2px 8px',
+         border: '1px solid var(--color-border-subtle, #2a3a4a)',
+         borderRadius: '4px',
+         background: 'var(--color-bg-root, #0f0f0f)',
+         color: 'var(--sidebar-text-primary, #e5edf8)',
+         fontSize: '11px',
+         lineHeight: '16px',
+       }}
+     >
+       <span>{buildRailMotionMergeNoticeCopy(notice, { undoable })}</span>
+       <button
+         type="button"
+         class="physics-paint-roto-key-icon-button"
+         aria-label="Dismiss rail merge notice"
+         onClick={() => dismissRailMotionMergeNotice()}
+       >
+         Dismiss
+       </button>
+     </div>
+   );
+ }
+
+ /**
+  * quick-261025-awl (D-04): the Raster header action, rendered immediately
+  * before Tools. The leaf owns the confirmation state (a ref-held signal — never
+  * useState), the styled tooltip and the portaled dialog, so the strip body
+  * never subscribes to ownership: only this leaf reads `props.ownerSignal.value`.
+  *
+  * The dialog reuses the Memory-tab confirmation classes and focus contract:
+  * Cancel is focused synchronously on open, Escape closes, Tab cycles the two
+  * buttons. Confirm closes first, then forwards the frame — the Studio handler
+  * re-validates everything and does the pixel-preserving purge.
+  */
+ function PhysicsPaintRasterKeyControl(props: {
+   currentFrame: Signal<number>;
+   ownerSignal: ReadonlySignal<FrameScriptOwner>;
+   ready: boolean;
+   playbackActive: boolean;
+   mutationLocked: boolean;
+   onRasterKey?: (frame: number) => void;
+   onRasterRail?: (kind: RasterRailTarget['kind'], railId: string) => void;
+   railTargetSignal?: ReadonlySignal<RasterRailTarget | null>;
+ }) {
+   const tooltip = useStyledTooltip();
+   // One signal for the lifetime of the leaf — created in a ref (never a fresh
+   // signal per render, never useState).
+   const openRef = useRef<Signal<boolean> | null>(null);
+   if (openRef.current === null) openRef.current = signal(false);
+   const openSignal = openRef.current;
+   const open = openSignal.value;
+   const dialogRef = useRef<HTMLDivElement | null>(null);
+   const triggerRef = useRef<HTMLSpanElement | null>(null);
+   const cancelRef = useRef<HTMLButtonElement | null>(null);
+
+   const frame = props.currentFrame.value;
+   const owner = props.ownerSignal.value;
+   // quick-261101-f5v (D-01): a selected key rail wins the Raster scope. The
+   // rail target arrives as a signal REFERENCE and is read HERE only, so the
+   // strip body and the memoized chrome never subscribe to it.
+   const railTarget = props.railTargetSignal?.value ?? null;
+   const railMode = railTarget !== null;
+   const presentation = railTarget !== null
+     ? resolveRasterRailPresentation({
+       hasScript: railTarget.hasScript,
+       ready: props.ready,
+       playbackActive: props.playbackActive,
+       mutationLocked: props.mutationLocked,
+       frameCount: railTarget.frames.length,
+     })
+     : resolveRasterKeyPresentation({
+       hasScript: owner !== null,
+       ready: props.ready,
+       playbackActive: props.playbackActive,
+       mutationLocked: props.mutationLocked,
+     });
+
+   // Modal focus: Cancel is the quiet default, exactly like the Memory tab.
+   // Synchronous (no rAF) so the harness and Node tests can run the whole flow.
+   useEffect(() => {
+     if (!open) return;
+     const target = cancelRef.current;
+     if (target && typeof target.focus === 'function') target.focus();
+   }, [open]);
+
+   // The strip clips overflow, so the dialog portals to document.body and is
+   // positioned above the strip with the shared toolbox placement helper
+   // (start hidden, then set left/top/visibility — the PhysicsPaintToolboxPopover
+   // contract).
+   useLayoutEffect(() => {
+     const dialog = dialogRef.current;
+     const trigger = triggerRef.current;
+     if (!open || !dialog || !trigger) return;
+     const panelSize = { width: dialog.offsetWidth, height: dialog.offsetHeight };
+     const anchorRect = trigger.getBoundingClientRect();
+     const strip = trigger.closest('.physics-paint-workflow-strip');
+     const stripRect = strip ? strip.getBoundingClientRect() : anchorRect;
+     const placement = computeToolboxPopoverPlacement({ anchorRect, stripRect, panelSize });
+     dialog.style.left = `${placement.left}px`;
+     dialog.style.top = `${placement.top}px`;
+     dialog.style.visibility = 'visible';
+   });
+
+   const closeConfirm = () => {
+     openSignal.value = false;
+   };
+   const confirmRaster = () => {
+     closeConfirm();
+     // quick-261101-f5v: the rail scope forwards the clicked rail identity; the
+     // Studio re-resolves it at call time. The key scope is unchanged.
+     if (railTarget !== null) {
+       props.onRasterRail?.(railTarget.kind, railTarget.railId);
+       return;
+     }
+     props.onRasterKey?.(props.currentFrame.peek());
+   };
+
+   // quick-261101-f5v (D-08): the dialog names the scope. A multi-key rail
+   // names its frame range and the skip rule; a ONE-key rail reuses the exact
+   // key copy with that rail's own frame, and the key scope keeps the current
+   // frame. An empty rail never opens a dialog (the control is disabled with
+   // the empty-rail reason).
+   const railRange = railTarget ? formatRasterRailRange(railTarget.frames) : '';
+   const multiKeyRail = railTarget !== null && railTarget.frames.length > 1;
+   const scopeFrame = railTarget !== null && railTarget.frames.length === 1
+     ? railTarget.frames[0]!
+     : frame;
+   const dialogAria = multiKeyRail ? `Raster rail keys ${railRange}` : `Raster key ${scopeFrame}`;
+   const dialogTitle = multiKeyRail ? `Raster rail keys ${railRange}?` : `Raster key ${scopeFrame}?`;
+   const dialogBody = multiKeyRail
+     ? 'Every scripted key on this rail loses its Brush and Water color script and keeps its painted pixels. Keys without cached pixels are skipped. Move, Select and replay are lost for those keys.'
+     : "This removes the key's Brush and Water color script and keeps the painted pixels. Move, Select and replay are lost for this key.";
+   const dialogConfirm = multiKeyRail ? 'Raster rail keys' : 'Raster key';
+
+   const dialog = open ? (
+     <div
+       ref={dialogRef}
+       class="physics-paint-memory-confirmation physics-paint-raster-confirmation"
+       role="dialog"
+       aria-modal="true"
+       aria-label={dialogAria}
+       style={{ visibility: 'hidden' }}
+       onKeyDown={(event) => {
+         if (event.key === 'Escape') {
+           event.preventDefault();
+           closeConfirm();
+           return;
+         }
+         if (event.key !== 'Tab') return;
+         const controls = Array.from(
+           dialogRef.current?.querySelectorAll<HTMLElement>(
+             'button:not(:disabled), [tabindex]:not([tabindex="-1"])',
+           ) ?? [],
+         );
+         if (!controls.length) return;
+         const first = controls[0]!;
+         const last = controls[controls.length - 1]!;
+         if (event.shiftKey && document.activeElement === first) {
+           event.preventDefault();
+           last.focus();
+         } else if (!event.shiftKey && document.activeElement === last) {
+           event.preventDefault();
+           first.focus();
+         }
+       }}
+     >
+       <strong>{dialogTitle}</strong>
+       <p class="physics-paint-memory-confirm-copy">
+         {dialogBody}
+       </p>
+       <div class="physics-paint-memory-confirm-actions">
+         <button
+           ref={cancelRef}
+           type="button"
+           class="physics-paint-memory-confirm-cancel"
+           onClick={closeConfirm}
+         >
+           Cancel
+         </button>
+         <button
+           type="button"
+           class="physics-paint-memory-confirm-ok destructive"
+           onClick={confirmRaster}
+         >
+           {dialogConfirm}
+         </button>
+       </div>
+     </div>
+   ) : null;
+
+   return (
+     <Fragment>
+       <span
+         ref={triggerRef}
+         class="physics-paint-roto-key-icon-action"
+         onPointerEnter={tooltip.onPointerEnter}
+         onPointerLeave={tooltip.onPointerLeave}
+       >
+         <button
+           type="button"
+           class="physics-paint-roto-key-icon-button"
+           aria-label={railMode ? 'Raster the rail' : 'Raster the key'}
+           aria-disabled={presentation.disabled ? 'true' : undefined}
+           onFocus={tooltip.onFocus}
+           onBlur={tooltip.onBlur}
+           onClick={() => {
+             if (presentation.disabled) return;
+             tooltip.hide();
+             openSignal.value = true;
+           }}
+           onKeyDown={(event) => {
+             if (!presentation.disabled) return;
+             if (event.key === 'Enter' || event.key === ' ') event.preventDefault();
+           }}
+         >
+           <span class="physics-paint-toolbox-badge-anchor">
+             <Stamp size={18} aria-hidden="true" />
+           </span>
+           <span class="physics-paint-roto-key-icon-label">Raster</span>
+         </button>
+         <PhysicsPaintStyledTooltip visible={tooltip.visible} region="bottom">
+           {buildGuardedActionTooltipCopy(
+             railMode
+               ? "Raster the rail — remove every key's script and keep the painted pixels."
+               : 'Raster the key — remove its script and keep the painted pixels.',
+             presentation.reason,
+           )}
+         </PhysicsPaintStyledTooltip>
+       </span>
+       {dialog && typeof document !== 'undefined' ? createPortal(dialog, document.body) : dialog}
+     </Fragment>
+   );
+ }
+
+ interface PhysicsPaintWorkflowStaticChromeProps {
+   currentFrame: Signal<number>;
+   capsuleText: Signal<string>;
+   /** Capsule icon tone: a warning triangle when the current message is an error. */
+   capsuleIsError: boolean;
+   /** 52.1 (warm progress): 0..100 while a blank key's settle gate holds the pen. */
+   warmProgress?: ReadonlySignal<number>;
+   ready: boolean;
+   playbackAvailable: boolean;
+   playbackActive: boolean;
+   /** quick-261025-awl (D-04): Raster header action — signal reference + stable callback. */
+   onRasterKey?: (frame: number) => void;
+   frameScriptOwner?: ReadonlySignal<FrameScriptOwner>;
+   /** quick-261101-f5v: the rail-scoped Raster bundle (same reference+callback shape). */
+   onRasterRail?: (kind: RasterRailTarget['kind'], railId: string) => void;
+   rasterRailTarget?: ReadonlySignal<RasterRailTarget | null>;
+   playbackTick: Signal<RotoCachedPlaybackTick | null> | null | undefined;
+   playbackLoop: boolean;
+   playbackFps: number;
