+ const PhysicsPaintWorkflowStaticChrome = memo(PhysicsPaintWorkflowStaticChromeImpl);
+
+ interface RotoTimelineCellButtonProps {
+   frame: number;
+   vm: RotoCellViewModel;
+   cellClass: string;
+   semanticKind: 'empty' | 'real-key' | 'generated';
+   cellKeyId: string | null;
+   dragEligible: boolean;
+   startsInterpolationSegment: boolean;
+   ariaLabel: string;
+   ariaSelected?: boolean;
+   tooltipCopy: string;
+   onCellPointerDown: (event: PointerEvent, frame: number, keyId: string) => void;
+   onCellClick: (frame: number, vm: RotoCellViewModel, event: MouseEvent) => void;
+   /** v2.0.1 (README §4): the cell matrix state and its owning rail type — the
+    *  four primitives below drive the data attributes and the palette custom
+    *  properties for this cell. */
+   railCellKind: TimelineCellKind;
+   railCellCycle?: 2 | 3;
+   railType: TimelineRailType;
+   railSelected: boolean;
+ }
+
+ /**
+  * Per-cell derivation bundle (38.1-04, Option A — 38.1-D-08 link 2, RESEARCH
+  * Pattern 3). Each entry holds the expensive per-cell derivations for one
+  * frame: `getRotoCellViewModel` (whose per-call cachedFrames filter/find scan
+  * is O(N)) and `getRotoCellFill` (O(N) some). `currentFrame` feeds nothing in
+  * these derivations except the view model's `current` overlay, so a pure
+  * frame change invalidates ONLY the previously-current and newly-current
+  * entries; every other entry serves the byte-identical cached value.
+  */
+ interface RotoCellDerivation {
+   vm: RotoCellViewModel;
+   fill: ReturnType<typeof getRotoCellFill>;
+ }
+
+ interface RotoCellDerivationCache {
+   physicalCellByAppFrame: ReadonlyMap<number, RotoPhysicalTimelineCell>;
+   cachedFrameByAppFrame: ReadonlyMap<number, PhysicPaintRotoCacheFrame>;
+   realCachedFrameSet: ReadonlySet<number>;
+   currentFrame: number;
+   entries: Map<number, RotoCellDerivation>;
+ }
+
+ /**
+  * One physical-frame cell with its own styled-tooltip controller (D-16/C-06).
+  * Hooks cannot run inside the physical-cell map in the strip body, so each cell is
+  * a child component owning one `useStyledTooltip` instance. The button keeps
+  * every `data-roto-*` attribute, class hook, and drag handler verbatim — only
+  * the native `title` is retired in favor of the styled tooltip (Pitfall 4).
+  */
+ function RotoTimelineCellButtonImpl(props: RotoTimelineCellButtonProps) {
+   recordPhysicsPaintPerformanceCounter('render.rotoTimelineCellButton');
+   const tooltip = useStyledTooltip();
+   // v2.0.1 (README §4): rebuild the presentation from the two primitives the
+   // memo compares (kind + cycle), then let the design module own the palette
+   // custom properties — the component never hardcodes a colour.
+   const railCellPresentation: TimelineCellPresentation = props.railCellCycle === undefined
+     ? { kind: props.railCellKind }
+     : { kind: props.railCellKind, cycle: props.railCellCycle };
+   const railCellStyle = timelineRailCellStyle(
+     railCellPresentation,
+     resolveTimelineRailPalette(props.railType, props.railSelected ? 'selected' : 'active'),
+     props.railSelected,
+   ) as unknown as CSSProperties;
+   return (
+     <span
+       class="physics-paint-roto-cell-anchor"
+       onPointerEnter={tooltip.onPointerEnter}
+       onPointerLeave={tooltip.onPointerLeave}
+     >
+       <button
+         type="button"
+         class={props.cellClass}
+         data-roto-app-frame={props.frame}
+         data-roto-kind={props.semanticKind}
+         data-roto-key-id={props.cellKeyId ?? undefined}
+         data-cell-kind={props.railCellKind}
+         data-cycle={props.railCellCycle}
+         data-rail-type={props.railType}
+         data-rail-selected={props.railSelected ? 'true' : undefined}
+         style={railCellStyle}
+         aria-label={props.ariaLabel}
+         aria-selected={props.ariaSelected === true ? 'true' : undefined}
+         onPointerDown={props.dragEligible && props.cellKeyId !== null
+           ? (event) => {
+               tooltip.hide();
+               props.onCellPointerDown(event as unknown as PointerEvent, props.frame, props.cellKeyId as string);
+             }
+           : undefined}
+         onFocus={tooltip.onFocus}
+         onBlur={tooltip.onBlur}
+         onClick={(event) => {
+           tooltip.hide();
+           props.onCellClick(props.frame, props.vm, event as unknown as MouseEvent);
+         }}
+       >
+         <span>{props.frame}</span>
+       </button>
+       <PhysicsPaintStyledTooltip visible={tooltip.visible} region="bottom">{props.tooltipCopy}</PhysicsPaintStyledTooltip>
+     </span>
+   );
+ }
+
+ // 52.1 (fresh-key glitch): the per-cell derivation cache full-invalidates
+ // whenever physicalCellByAppFrame identity changes (a fresh key inserts a new
+ // cell), handing EVERY cell a brand-new RotoCellViewModel object. The default
+ // memo identity check then re-renders all ~626 cells on each key creation even
+ // though their content is byte-identical — a ~157ms JS burst + DOM-diff churn
+ // inside the paint window. Compare VM CONTENT (not identity) so unchanged cells
+ // bail and only the frame(s) whose derivation actually changed re-render.
+ function rotoCellVmValuesEqual(a: RotoCellViewModel, b: RotoCellViewModel): boolean {
+   if (a.frame !== b.frame) return false;
+   if (a.baseMeaning !== b.baseMeaning) return false;
+   if (a.state !== b.state) return false;
+   if (a.label !== b.label) return false;
+   if (a.title !== b.title) return false;
+   if (a.ariaLabel !== b.ariaLabel) return false;
+   if (a.fillClass !== b.fillClass) return false;
+   if (a.isEditableTarget !== b.isEditableTarget) return false;
+   if (a.isCurrent !== b.isCurrent) return false;
+   if (a.isDirty !== b.isDirty) return false;
+   if (a.isPending !== b.isPending) return false;
+   if (a.overlays.length !== b.overlays.length) return false;
+   for (let i = 0; i < a.overlays.length; i++) {
+     if (a.overlays[i] !== b.overlays[i]) return false;
+   }
+   return true;
+ }
+
+ const RotoTimelineCellButton = memo(
+   RotoTimelineCellButtonImpl,
+   (prev, next) => prev.frame === next.frame
+     && prev.semanticKind === next.semanticKind
+     && prev.cellKeyId === next.cellKeyId
+     && prev.cellClass === next.cellClass
+     && prev.dragEligible === next.dragEligible
+     && prev.startsInterpolationSegment === next.startsInterpolationSegment
+     && prev.ariaLabel === next.ariaLabel
+     && prev.ariaSelected === next.ariaSelected
+     && prev.tooltipCopy === next.tooltipCopy
+     && prev.railCellKind === next.railCellKind
+     && prev.railCellCycle === next.railCellCycle
+     && prev.railType === next.railType
+     && prev.railSelected === next.railSelected
+     && prev.onCellPointerDown === next.onCellPointerDown
+     && prev.onCellClick === next.onCellClick
+     && rotoCellVmValuesEqual(prev.vm, next.vm),
+ );
+
+ /* ----------------------------------------------------------------------------
+  * 261008-ig1 Task 2 — the per-clip sound band children (D-01 multi-clip).
+  * HOOK-FREE by law: expanded by direct function call in tests, and the NARROW
+  * selection reads (`selectedSoundId.value`) live HERE — never in the strip
+  * body — so a band deselect re-renders exactly these vnodes
+  * (efx-preact-reactivity narrow-read). Declared BEFORE the strip export so
+  * the body source slice excludes them. Fail-closed: the stain child returns
+  * null without peaks (loading / missing source -> plain band).
+  * ------------------------------------------------------------------------- */
